/// Factorization fixtures covering published percentile anchors, outliers, and
/// the Symbolica 2.2 failure suite.
pub const POLYBENCH_FACTOR_CASES: [PolybenchFactorCase; 11] = [
    POLYBENCH_FACTOR_5_UNIFORM_32,
    POLYBENCH_FACTOR_5_UNIFORM_159,
    POLYBENCH_FACTOR_5_UNIFORM_163,
    POLYBENCH_FACTOR_5_UNIFORM_131,
    POLYBENCH_FACTOR_8_SHARP_178,
    POLYBENCH_FACTOR_8_SHARP_92,
    POLYBENCH_FACTOR_8_SHARP_84,
    POLYBENCH_FACTOR_8_SHARP_176,
    POLYBENCH_FACTOR_8_UNIFORM_44,
    POLYBENCH_FACTOR_8_UNIFORM_105,
    POLYBENCH_FACTOR_8_UNIFORM_159,
];

#[cfg(test)]
#[allow(dead_code, unused_imports)]
mod tests {
    use super::*;

    fn valid_sha256(value: &str) -> bool {
        value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
    }

    #[test]
    fn fixture_metadata_is_complete() {
        assert_eq!(POLYBENCH_GCD_CASES.len(), 12);
        assert_eq!(POLYBENCH_FACTOR_CASES.len(), 11);

        for case in POLYBENCH_GCD_CASES {
            assert!(matches!(case.variables().len(), 5 | 8));
            assert!(valid_sha256(case.expanded_input_sha256));
            assert!(case.expected_input_terms.into_iter().all(|terms| terms > 0));
            match case.construction {
                PolybenchGcdConstruction::Nontrivial {
                    left_cofactor,
                    right_cofactor,
                    common_factor,
                    expected_factor_terms,
                } => {
                    assert!(!left_cofactor.is_empty());
                    assert!(!right_cofactor.is_empty());
                    assert!(!common_factor.is_empty());
                    assert!(expected_factor_terms.into_iter().all(|terms| terms > 0));
                }
                PolybenchGcdConstruction::Trivial {
                    left_factors,
                    right_factors,
                    expected_factor_terms,
                } => {
                    assert!(left_factors.into_iter().all(|factor| !factor.is_empty()));
                    assert!(right_factors.into_iter().all(|factor| !factor.is_empty()));
                    assert!(expected_factor_terms.into_iter().all(|terms| terms > 0));
                }
            }
        }

        for case in POLYBENCH_FACTOR_CASES {
            assert!(matches!(case.variables().len(), 5 | 8));
            assert!(case.factors.into_iter().all(|factor| !factor.is_empty()));
            assert!(
                case.expected_factor_terms
                    .into_iter()
                    .all(|terms| terms > 0)
            );
            assert!(case.expected_input_terms > 0);
            assert!(valid_sha256(case.expanded_input_sha256));
        }
    }

    #[test]
    fn gcd_construction_marks_the_noninjected_case() {
        assert_eq!(
            POLYBENCH_GCD_CASES
                .into_iter()
                .filter(|case| {
                    matches!(case.construction, PolybenchGcdConstruction::Trivial { .. })
                })
                .count(),
            1
        );
    }

    #[test]
    fn published_percentile_anchor_selection_is_stable() {
        for case in [
            POLYBENCH_GCD_8_UNIFORM_56,
            POLYBENCH_GCD_8_UNIFORM_168,
            POLYBENCH_GCD_8_UNIFORM_188,
            POLYBENCH_GCD_8_SHARP_53,
            POLYBENCH_GCD_8_SHARP_35,
            POLYBENCH_GCD_8_SHARP_140,
        ] {
            assert!(POLYBENCH_GCD_CASES.contains(&case));
        }

        for case in [
            POLYBENCH_FACTOR_5_UNIFORM_159,
            POLYBENCH_FACTOR_5_UNIFORM_163,
            POLYBENCH_FACTOR_5_UNIFORM_131,
            POLYBENCH_FACTOR_8_SHARP_92,
            POLYBENCH_FACTOR_8_SHARP_84,
            POLYBENCH_FACTOR_8_SHARP_176,
        ] {
            assert!(POLYBENCH_FACTOR_CASES.contains(&case));
        }
    }
}
